import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第119章 旧地址","description":"","frontmatter":{},"headers":[],"relativePath":"第119章_旧地址.md","filePath":"第119章_旧地址.md"}'),_={name:"第119章_旧地址.md"};function r(u,p,n,s,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第119章-旧地址" tabindex="-1">第119章 旧地址 <a class="header-anchor" href="#第119章-旧地址" aria-label="Permalink to &quot;第119章 旧地址&quot;">​</a></h1><p>她给我寄过一盒东西，那盒东西我没有拿到。</p><p>这件事我要从头讲，因为它是我这几年想得最多的一件事。</p><p>那年年底我们要把仓库清空。</p><p>她那边的生意停了，剩下的货要分掉。</p><p>我们分得很清楚。</p><p>她拿她的，我拿我这几年垫的钱抵剩下的。</p><p>我们那天在手机上把这些讲完了，一共三十七句。</p><p>最后她说了一句。</p><p>她说，我这里还有几样东西在你那边。</p><p>我说，哪几样。</p><p>她说，我也不知道。</p><p>她说，我这边那个柜子里翻出来一些，我认不全。</p><p>她说，我把那一盒寄给你，你替我看一下哪些是我的，哪些是你的。</p><p>我说，你寄到我这边来，地址我发你。</p><p>她说，我有。</p><p>我说，那个地址换了。</p><p>她说，我有旧的。</p><p>我说，旧的那个我三年没住了。</p><p>她隔了一会儿。</p><p>她说，我知道。</p><p>我说，你知道你还寄。</p><p>她说，因为我这边只有那一个能打得出来。</p><p>她说，我手机里那个地址是三年前存的，我每次要寄东西我都从那里复制。</p><p>她说，我今天不想重新问你一个新地址。</p><p>她说，我不是找不到你。</p><p>她说，我是今天不想再给你一个新的位置。</p><p>我看这几句，看了很久。</p><p>我说，那你还是寄到新地址。</p><p>她说，不。</p><p>她说，就寄那个。</p><p>她说，我想试一下。</p><p>我说，试什么。</p><p>她说，试一下它能不能到。</p><p>我说，它到不了。</p><p>她说，我知道到不了。</p><p>她说，我就是想让它到不了。</p><p>她说，你要是不说话我就这么寄。</p><p>我说，你寄。</p><p>她那天下午把那一盒寄出来了。</p><p>那一盒里面有：</p><p>一支笔（那年二月她要在展上给我写字的那支）。</p><p>一根头发绳。</p><p>两张她自己的图。</p><p>一本她自己印的小册子。</p><p>一个我那年给她刻的那个小木头东西。</p><p>还有一张纸，纸上写的是一串数字。</p><p>那串数字是我那年二月她退票的那个订单号。</p><p>她把这个也放进去了。</p><p>那一盒东西后来没有到我手上。</p><p>快递那边给的说法是：地址无人签收，电话不是本人，退回件超期，做无主处理。</p><p>无主处理是什么意思，我打那个客服电话问了半小时。</p><p>那个客服说，就是丢了。</p><p>我说，寄件人是谁。</p><p>他说，你等一下，我查。</p><p>他说，这边看不到，你让寄件人查。</p><p>我那天晚上给她发了一句。</p><p>我说，那个客服说让寄件人查。</p><p>她说，我查了。</p><p>她说，他们说超期了。</p><p>我说，那你今天什么感觉。</p><p>她隔了很久。</p><p>09:31</p><p>她说，我今天在银行那个柜台前面站着，我站在那里听那个男的讲&quot;超期了&quot;。</p><p>她说，我那时候心里第一反应不是心疼。</p><p>她说，我第一反应是我终于可以把这件事报给你了。</p><p>她说，我这一辈子办砸一件事，我要拿到一个别人能听到的说法，我才敢承认它砸了。</p><p>她说，我今天拿到&quot;超期了&quot;这三个字，我就可以讲&quot;它丢了，不是我要它丢的&quot;。</p><p>她说，闻迟，我今天给你讲这个，是因为我不想再拿一个字盖一件事。</p><p>她说，我是故意寄那个旧地址的。</p><p>她说，我知道它到不了。</p><p>她说，我要它到不了。</p><p>她说，那一盒东西我要是寄到你现在那儿，你收了，你要打开，你要一件一件给我回。</p><p>她说，你要回我就得接。</p><p>她说，我今年接不了。</p><p>她说，我用一千二百块的运费，买了一个&quot;它丢了&quot;。</p><p>我说，那根头发绳。</p><p>她说，怎么了。</p><p>我说，那根绳子是我那年十一月给你寄的那一包的。</p><p>她说，我知道。</p><p>我说，你留了三年。</p><p>她说，我留了三年。</p><p>我说，那你为什么把它放在那一盒里。</p><p>她说，因为我要它丢。</p><p>她说，我留着那根绳子，我这辈子每一天都在算我今天有没有资格讲一句我想你。</p><p>她说，我今天把它放进那个盒子里，我让它丢，我明天就不用算了。</p><p>我说，那你想不想。</p><p>她隔了很久。</p><p>09:44</p><p>她说，你别问这句。</p><p>我说，我就问这一句。</p><p>她说，我不想讲。</p><p>我说，你说一句我就不问了。</p><p>她说，我要是讲了，你今天晚上就要开始想明天要干什么。</p><p>她说，你一想你明天要干什么，你后天就要出现在我那个城市。</p><p>她说，我不要你出现。</p><p>她说，我不是嫌你。</p><p>她说，我是我一见到你，我这三年全部白弄。</p><p>她说，我这三年每天都在把那盒东西丢掉一点。</p><p>她说，我今天把最后一盒丢了。</p><p>她说，你今天要是让我看见你，我明天就要把所有捡回来。</p><p>她说，我捡不回来。</p><p>我说，那我不去。</p><p>她说，好。</p><p>她说，谢谢你今天不讲那句&quot;我可以不去&quot;。</p><p>她说，你今年讲了&quot;那我不去&quot;。</p><p>她说，你这句话我这三年里等到过一次。</p><p>她说，我今天等到。</p><p>她说，我今天等到了，我今天晚上能睡。</p><p>那天夜里我把那个&quot;到不了&quot;的快递单，从头到尾查了一遍。</p><p>我查到那个网点，我打过去。</p><p>我说我要查一个无主件的销毁记录。</p><p>那个小姑娘说，先生，我们这里没有这个流程，你打总部。</p><p>我打总部。</p><p>我在电话前面坐了四十分钟。</p><p>我最后拿到的是一句话：查不到。</p><p>我那天晚上给她发了一句。</p><p>我说，我今天去查了。</p><p>她说，查到了吗。</p><p>我说，没有。</p><p>她说，你为什么要去查。</p><p>我说，我不知道。</p><p>她说，你知道。</p><p>她说，你今天去查是因为你想要它是丢的，你想要它丢得有一个说法。</p><p>她说，你跟我今天早上一模一样。</p><p>她说，我们两个今天拿着同一张&quot;超期了&quot;，各自在电话前面坐了四十分钟。</p><p>她说，你今年三十一了。</p><p>她说，你还在找那张纸。</p><p>我说，我不找了。</p><p>她说，你找。</p><p>她说，你别在我这儿讲你不找。</p><p>她说，你找你的，我丢我的。</p><p>她说，我们两个今年就靠这个过日子。</p><p>那天夜里我在本子上写了一行。</p><p>我写：她把最后一盒东西寄到一个空地址上，她要我别去捡。</p><p>我写：我答应了。</p><p>我写：我今年第一次答应她一件真话。</p>',137)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
